@router.get("/install/{plugin_id}", summary="安装插件", response_model=schemas.Response)
async def install(
    plugin_id: str,
    repo_url: Optional[str] = "",
    release_version: Optional[str] = None,
    force: Optional[bool] = False,
    _: User = Depends(get_current_active_superuser_async),
) -> Any:
    """
    安装插件
    """
    # 已安装插件
    install_plugins = SystemConfigOper().get(SystemConfigKey.UserInstalledPlugins) or []
    # 首先检查插件是否已经存在，并且是否强制安装，否则只进行安装统计
    plugin_helper = PluginHelper()
    if not force and plugin_id in PluginManager().get_plugin_ids():
        if repo_url:
            compatible_message = await plugin_helper.async_get_plugin_system_version_check_message(
                plugin_id, repo_url
            )
            if compatible_message:
                return schemas.Response(success=False, message=compatible_message)
        await MoviePilotServerHelper.async_install_plugin_reg(plugin_id=plugin_id, repo_url=repo_url)
    else:
        # 插件不存在或需要强制安装，下载安装并注册插件
        if repo_url:
            state, msg = await plugin_helper.async_install(
                pid=plugin_id, repo_url=repo_url, release_version=release_version, force_install=force
            )
            # 安装失败则直接响应
            if not state:
                return schemas.Response(success=False, message=msg)
            await MoviePilotServerHelper.async_install_plugin_reg(plugin_id=plugin_id, repo_url=repo_url)
        else:
            # repo_url 为空时，也直接响应
            return schemas.Response(
                success=False, message="没有传入仓库地址，无法正确安装插件，请检查配置"
            )
    # 安装插件
    if plugin_id not in install_plugins:
        install_plugins.append(plugin_id)
        # 保存设置
        await SystemConfigOper().async_set(
            SystemConfigKey.UserInstalledPlugins, install_plugins
        )
    # 重新加载插件
    await run_in_threadpool(reload_plugin, plugin_id)
    return schemas.Response(success=True)

def stop(self, pid: Optional[str] = None):
    """
    停止插件服务
    :param pid: 插件ID，为空停止所有插件
    """
    # 停止插件
    if pid:
        logger.info(f"正在停止插件 {pid}...")
        plugin_obj = self._running_plugins.get(pid)
        if not plugin_obj:
            # 指定插件可能在上次加载时已导入模块但初始化失败，此时不会进入运行态列表。
            # 仍需继续清理类缓存和 sys.modules，避免后续热重载反复复用旧模块。
            logger.debug(f"插件 {pid} 不存在或未加载")
            plugins = {}
        else:
            plugins = {pid: plugin_obj}
    else:
        logger.info("正在停止所有插件...")
        plugins = self._running_plugins
    for plugin_id, plugin in plugins.items():
        eventmanager.disable_event_handler(type(plugin))
        self.__stop_plugin(plugin)
    # 清空对象
    if pid:
        # 清空指定插件
        self._plugins.pop(pid, None)
        self._running_plugins.pop(pid, None)
        # 清除插件模块缓存，包括所有子模块
        self._clear_plugin_modules(pid)
    else:
        # 清空
        self._plugins = {}
        self._running_plugins = {}
        # 清除所有插件模块缓存
        self._clear_plugin_modules()
